import { useContext } from "react";
import { BoardContext, BoardProvider } from "./BoardContext";
import "./App.css";

function Board() {
  const { state: columns, dispatch } = useContext(BoardContext);

  const handleDragStart = (e, taskId, sourceColId) => {
    e.dataTransfer.setData("taskId", taskId);
    e.dataTransfer.setData("sourceColId", sourceColId);
  };

  const handleDrop = (e, targetColId) => {
    dispatch({
      type: "MOVE_TASK",
      payload: {
        taskId: parseInt(e.dataTransfer.getData("taskId")),
        sourceColId: e.dataTransfer.getData("sourceColId"),
        targetColId
      }
    });
  };

  return (
    <div className="board-container">
      <h1>Kanban Board</h1>
      <div className="board">
        {columns.map(col => (
          <div 
            key={col.id} 
            className="column"
            onDragOver={(e) => e.preventDefault()}
            onDrop={(e) => handleDrop(e, col.id)}
          >
            <h3>{col.title}</h3>
            {col.tasks.map(task => (
              <div 
                key={task.id} 
                className="task"
                draggable={true}
                onDragStart={(e) => handleDragStart(e, task.id, col.id)}
              >
                {task.text}
              </div>
            ))}
          </div>
        ))}
      </div>
    </div>
  );
}

export default function App() {
  return (
    <BoardProvider>
      <Board />
    </BoardProvider>
  );
}
